#ifndef URSATZ_TESTS_ACCURACY_FIXTURES_H
#define URSATZ_TESTS_ACCURACY_FIXTURES_H

#include <stdbool.h>
#include <stddef.h>

#include "accuracy_report.h"

/*
 * The existing fixture-based accuracy checks of tests/integration, read through the harness. Each of those tests
 * stays as it is: it is compiled into the harness with its main renamed (generated by CMake, see CMakeLists.txt), run with its
 * output captured, and its whole-chain summary lines are read ("N of M"). They are the tests' own numbers, on
 * their own fixtures (tests/fixtures/annotations/ and the framework-v1 corpus), so a change to a summary line
 * shows up here as a missing metric, not a silent zero.
 *
 * Reported (the whole-chain runs; the "adapter alone" runs feed the adapter the annotation and are not a chain):
 *   cadences (five reference pieces, per piece), phrase boundaries / theme types / expansions (the five pieces
 *   pooled), the phrase model labels (Mozart 545), melody (Bach 114), motives (Mozart 545), syncopations and
 *   hyperdownbeats (Field 5), texture (Field 1), schemas and sequences (the galant fixture).
 * Not reported: the voice leading report (it lists findings, it does not score against an annotation).
 */

/* Runs the tests and adds their metrics to report. False, with message, when a summary line is missing. */
bool accuracy_collect_fixtures(AccuracyReport *report, char *message, size_t message_size);

#endif
